pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 time1, uint256 time2) public {
        // Restrict to the two exact msg.value values that can ever pass the require:
        // 10 ether (reference always) or 9 ether (mutant only). The reference reverts on 9 ether,
        // but we are testing the non-revert path: only calls that succeed are considered.
        vm.assume(amount1 == 9 ether || amount1 == 10 ether);
        vm.assume(amount2 == 9 ether || amount2 == 10 ether);

        // Make timestamps strictly increasing to satisfy the require
        time2 = bound(time2, time1 + 1, type(uint256).max);
        vm.warp(time1);

        // First call
        vm.deal(address(this), amount1);
        bool ok1;
        try c.fallback{value: amount1}() { ok1 = true; } catch { ok1 = false; }

        // Record pastBlockTime after first call
        uint256 afterFirst = c.pastBlockTime();

        vm.warp(time2);
        // Second call
        vm.deal(address(this), amount2);
        bool ok2;
        try c.fallback{value: amount2}() { ok2 = true; } catch { ok2 = false; }

        uint256 afterSecond = c.pastBlockTime();

        // For all successful calls, the invariant holds:
        // If a call succeeds, pastBlockTime must equal the block.timestamp of that call plus 1.
        // The reference only allows 10 ether, so the second call cannot mix states from 9 ether.
        // The mutant allows 9 ether, making afterSecond potentially violate this relation when sequences
        // mix 9 ether and 10 ether, while the reference either reverts or enforces the relation.
        if (ok1) {
            assertTrue(afterFirst == time1 + 1);
        }
        if (ok2) {
            assertTrue(afterSecond == time2 + 1);
        }
        // The reference will never violate this; the mutant will when a 9 ether call succeeds intermixed.
        // The fuzzer can find sequences where ok1 or ok2 is true on the mutant but the timestamp relation fails.
        // Actually the mutant just uses 9 ether instead of 10 ether, so the relation still holds for the call that succeeded.
        // The real divergence is that the reference reverts on 9 ether while the mutant succeeds, so the state progresses.
        // To catch that, we assert that a call with 9 ether MUST revert on the reference.
        // The reference passes because it always reverts on 9 ether; the mutant fails because it can succeed.
        // We'll instead make the assertion about the overall pastBlockTime progression: after two calls that both succeed,
        // pastBlockTime must be strictly greater than the previous timestamp. But that's trivially true.
        // We need a property that the reference satisfies but the mutant can break.
        // The reference only allows 10 ether; the mutant allows 9 ether as well. So the set of successful call values differs.
        // We can assert: For any successful call, the msg.value is exactly 10 ether.
        // This is true for reference, false for mutant (it can succeed with 9 ether).
        // But we need to check this without assert on msg.value inside the try (can't).
        // We can observe that if a 9 ether call succeeds, it updates pastBlockTime, which then can affect subsequent calls.
        // A property: the sum of successful msg.value (which we know as the fuzz parameter) equals the change in contract balance.
        // But contract balance also can be transferred to sender on block.number % 15 == 0.
        // Better: if a call with 9 ether succeeds, that is a violation for the reference.
        // We'll assert that a call with 9 ether always reverts on the reference.
        // We measure revert status based on fuzzed amount.
        if (amount1 == 9 ether) {
            assertTrue(!ok1);
        }
        if (amount2 == 9 ether) {
            assertTrue(!ok2);
        }
    }
}

