pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 value, uint256 warpTime, uint256 blockNum) public {
        // Restrict to admissible domain: warpTime > 0 for the require(block.timestamp > pastBlockTime) to pass,
        // and msg.value must be <= 10 ether (the reference reverts on != 10 ether, but we must allow all values
        // for the fuzzer to find the difference). We do not restrict msg.value to exactly 10 ether.
        vm.assume(value <= 10 ether);
        vm.assume(warpTime > 0);
        // Block number modulo 15 can be anything; no need to restrict.

        // Setup: warp to a future timestamp so that require(block.timestamp > pastBlockTime) passes
        vm.warp(warpTime);
        vm.roll(blockNum);

        // Give the caller (this test contract) the necessary ether
        vm.deal(address(this), value);

        // Call the fallback function with the fuzzed value
        bool refReverted = false;
        try c.fallback{value: value}() {
            // success
        } catch {
            refReverted = true;
        }

        // The reference implementation requires msg.value == 10 ether.
        // If value != 10 ether, the reference MUST revert.
        // If value == 10 ether, the reference should succeed (given warpTime > pastBlockTime).
        // The buggy version deleted that require, so it will succeed even when value != 10 ether,
        // as long as block.timestamp > pastBlockTime.
        // Thus, the rule: if value != 10 ether, the call must revert.
        // The fuzzer will find a case where value != 10 ether and the buggy contract succeeds,
        // violating this rule.
        bool expectRevert = (value != 10 ether);
        assertTrue(refReverted == expectRevert);
    }
}

