        vm.roll(blockNum);
        uint256 timestamp = 100;
        vm.warp(timestamp);

        // First call: send exactly 10 ether
        address alice = address(0x1000);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "first call failed unexpectedly");

