pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 timeAdvance, uint256 blockNum) public {
        // timeAdvance controls the warp forward; wide domain, only assume > 0 to advance time
        vm.assume(timeAdvance > 0);
        // blockNum controls the block number; wide domain
        vm.assume(blockNum < type(uint64).max); // avoid overflow on block.number

        uint256 prevBalance = address(c).balance;
        uint256 prevPast = c.pastBlockTime();

        // Set up timestamp and block number; the bug misses the timestamp check,
        // allowing a same-block call to exploit the incorrect pastBlockTime update
        vm.warp(block.timestamp + timeAdvance);
        vm.roll(blockNum);

        address sender = address(0x1234);
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        // Use low-level call so we can check success without reverting the test on failure
        (bool success,) = address(c).call{value: 10 ether}("");
        // If the call reverts, the property is vacuously true: balance unchanged.
        // The property only makes a claim when the call succeeds.
        if (success) {
            // After a successful call, if block.number % 15 != 0, the contract balance
            // MUST be exactly prevBalance + 10 ether.
            // The reference always satisfies this because it never transfers in that case.
            // The mutant can break it when the same-block timestamp check is missing,
            // allowing pastBlockTime to be set such that a later condition may trigger
            // unintended transfer, but here we catch the immediate balance mismatch
            // when the mutant incorrectly performs the transfer on a non-multiple-of-15 block.
            if (block.number % 15 != 0) {
                assertTrue(address(c).balance == prevBalance + 10 ether);
            }
        }
    }
}

