pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 reentryDepth) public {
        // reentryDepth controls how many times the attacker re-enters; bound it to keep the fuzz domain wide but practical
        bound(reentryDepth, 1, 20);
        // Deploy a re-entrant attacker that calls back into c
        ReentrantAttacker attacker = new ReentrantAttacker();
        // Fund the attacker with enough ether for the initial fallback + reentries
        uint256 totalValue = (uint256(reentryDepth) + 1) * 10 ether;
        vm.deal(address(attacker), totalValue);
        // Set block.number so that block.number % 15 != 0 for all reentried calls (attacker calls back at same block)
        vm.roll(1); // block.number = 1, 1 % 15 = 1
        // Warp to a timestamp after c's initial pastBlockTime (0), so the reference's check passes
        vm.warp(1000);
        // Drive c through the attacker
        attacker.attack{value: totalValue}(address(c), reentryDepth);
        // Assert: After the call, if the contract did not transfer (block.number % 15 != 0), c's balance should be > 0.
        // The reference accumulates all ether; the mutant with missing timestamp check allows re-entrant drain.
        assertTrue(address(c).balance > 0);
    }
}

contract ReentrantAttacker {
    uint256 private depth;
    function attack(address payable target, uint256 _depth) external payable {
        depth = _depth;
        target.call{value: 10 ether}("");
    }
    receive() external payable {
        if (depth > 0) {
            depth--;
            // Re-enter the original target with another 10 ether
            payable(msg.sender).call{value: 10 ether}("");
        }
    }
}

