pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 blockDelta, uint256 blockNumOffset) public {
        // Constrain to admissible domain: msg.value must be 10 ether, blockDelta > 0 for timestamp increase,
        // and we avoid block.number % 15 == 0 to prevent self-destruction/transfer that complicates balance.
        uint256 val = 10 ether;
        vm.assume(amount1 == val && amount2 == val);
        vm.assume(blockDelta > 0 && blockDelta < 365 days);
        vm.assume(blockNumOffset + 1 <= type(uint256).max && blockNumOffset + 2 <= type(uint256).max);
        // Set block number so that neither call hits block.number % 15 == 0
        vm.assume((blockNumOffset + 1) % 15 != 0);
        vm.assume((blockNumOffset + 2) % 15 != 0);

        // First fallback call
        vm.deal(address(this), val);
        vm.roll(blockNumOffset + 1);
        vm.warp(block.timestamp);
        (bool ok1,) = address(c).call{value: val}("");
        vm.assume(ok1); // only consider inputs where first call succeeds

        // Advance block.timestamp by blockDelta, and block.number by 1
        vm.roll(blockNumOffset + 2);
        vm.warp(block.timestamp + blockDelta);

        // Second fallback call
        vm.deal(address(this), val);
        (bool ok2,) = address(c).call{value: val}("");
        vm.assume(ok2); // only consider inputs where second call succeeds

        // After two successful calls with increasing timestamp, pastBlockTime must have been updated at least once.
        // Since the correct contract sets pastBlockTime = block.timestamp + 1 on each call,
        // after the second call we must have pastBlockTime >= block.timestamp - 1 (allowing for 1-second margin).
        // The mutant never updates pastBlockTime, so it stays at 0, failing this for any block.timestamp > 1.
        assertTrue(c.pastBlockTime() >= block.timestamp - 1);
    }
}

