pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum1, uint256 blockNum2, uint256 timestamp) public {
        vm.assume(blockNum1 < blockNum2);
        vm.assume(blockNum1 % 15 != 0);
        vm.assume(blockNum2 % 15 == 0);
        vm.assume(timestamp > 0);
        uint256 valuePerCall = 10 ether;
        address alice = address(0x1);
        vm.deal(alice, valuePerCall * 2);
        // First call with blockNum1 that does not drain
        vm.roll(blockNum1);
        vm.warp(timestamp);
        vm.prank(alice);
        c.f{value: valuePerCall}();
        // Second call with blockNum2 in same timestamp
        vm.roll(blockNum2);
        vm.warp(timestamp);
        vm.prank(alice);
        c.f{value: valuePerCall}();
        // After a draining call (blockNum2 % 15 == 0), balance must be 0
        assertTrue(address(c).balance == 0);
    }
}
